    for (sr,sc) in sqs:
        cr,cc=sr+1,sc+1
        for c2 in range(W):
            if g[cr][c2]==0: g[cr][c2]=1
        for r2 in range(H):
            if g[r2][cc]==0: g[r2][cc]=1
        def in_sq(a,b): return sr<=a<=sr+2 and sc<=b<=sc+2
        for bc in vbars:
            Q=(cr,bc)
            if in_sq(*Q): continue
            for a in range(Q[0]-1,Q[0]+2):
                for b in range(Q[1]-1,Q[1]+2):
                    if 0<=a<H and 0<=b<W and not in_sq(a,b): g[a][b]=1
        for br in hbars:
            Q=(br,cc)
            if in_sq(*Q): continue
            for a in range(Q[0]-1,Q[0]+2):
                for b in range(Q[1]-1,Q[1]+2):
                    if 0<=a<H and 0<=b<W and not in_sq(a,b): g[a][b]=1
    return g
